const n=[{id:"suggestion-S01",title:"Peerdeman et al. · 2016 · Expectation interventions for patients’ pain",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 pooled studies involving 1,256 selected patients found reduced reported pain after expectation interventions: g=.61, 95% CI .42 to .79; bias-adjusted .43, .24 to .62.",limitation:"Clinical interventions differ from a self-written phrase. High heterogeneity; reported pain is not cure of its cause. Anxiety sensitivity estimate after removing an outlier was .03, CI −.21 to .26."},{id:"suggestion-S02",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Values affirmation paired with health information showed small average differences in message acceptance, intentions and behavior across 144 outcome tests. Behavior: d=.32, 95% CI .19 to .44.",limitation:"144 tests are not necessarily distinct studies. Outcome participant counts overlap. These results do not establish effects of values writing alone, positive chanting or ODA’s short adult exercise."},{id:"suggestion-S03",title:"Kross et al. · 2014 · Distanced self-talk experiments",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven short experiments involved 585 people. Study 2 used three-minute name or non-first-person reflection before a social interaction and found better observer-rated performance.",limitation:"Mostly student and social-evaluation settings. Preinteraction anxiety did not significantly improve in Study 2; later recovery was clearer. ODA’s shorter advice-and-action adaptation is not treatment or a guaranteed effect."},{id:"suggestion-S04",title:"Hatzigeorgiadis et al. · 2011 · Self-talk and sport performance",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 studies, 62 effects and 2,741 participants found an average sport-task performance benefit: d+=.48, 95% CI .38 to .58. Task and training subgroup estimates varied.",limitation:"Some designs were uncontrolled. Moderator comparisons do not establish optimal doses or universal instructional superiority. Office-work transfer and Gallwey’s whole framework were not tested."},{id:"suggestion-S05",title:"Zhang et al. · 2025 · Self-affirmation and well-being",url:"https://hub.hku.hk/handle/10722/366517",type:"research",finding:"The institutional abstract reports 67 articles and 129 independent tests in nonclinical populations, with small average benefits in self-perception and well-being.",limitation:"Full methods, participant total, confidence intervals, exact effect metric and follow-up durations were unavailable. This does not validate every affirmation script or a named ritual."},{id:"suggestion-S06",title:"Wang, Wang & Gai · 2021 · Outcome, obstacle and response plans",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles, 24 independent effects and 15,907 participants found an average goal-attainment benefit from mental contrasting with if–then plans: g=.336, CI .229 to .443; bias-adjusted .242, .143 to .342.",limitation:"Methods and controls varied. This does not validate the assembled ODA card, positive wording as the active ingredient, or splitting fantasy at bedtime from planning next morning."},{id:"suggestion-S07",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"The abstract reports worse immediate responses for some low-self-esteem participants repeating a strongly positive statement, with limited benefits at higher self-esteem.",limitation:"Original Ns, repetition count and numerical effects were not verified. Two later studies did not reproduce the pattern. No clinical threshold or universal mismatch mechanism is established."},{id:"suggestion-S08",title:"Flynn & Bordieri · 2020 · Affirmation replication studies",url:"https://contextualscience.org/publications/flynn_bordieri_2020",type:"research",finding:"Two university analogue studies, approximately 225 and 237 participants, did not reproduce the predicted mood, state-self-esteem or trait-self-esteem moderation pattern.",limitation:"Authors’ abstract only. Numerical effects, confidence intervals and precision were unavailable. A null result establishes neither universal benefit nor universal harmlessness."},{id:"suggestion-S09",title:"Lally et al. · 2010 · Habits in everyday life",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 volunteers repeated eating, drinking or activity behaviors in recurring contexts over 84 days. Time to modeled automaticity varied substantially among 39 acceptable models.",limitation:"Observational study, not an affirmation trial. The median 66-day estimate is not a deadline; some estimates extend beyond observation. No evidence of automaticity by Friday or a permanent 21-day change."},{id:"suggestion-S10",title:"Paller, Creery & Schechtman · 2021 · Memory and sleep",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"The review discusses reactivation of previously learned material during sleep and limited simple associative sleep learning.",limitation:"Narrative review, no pooled effect. Memory processing does not establish drowsy receptivity to self-help commands, Murphy’s ritual, complex skills installed by recordings or thought-driven outcomes."},{id:"suggestion-S11",title:"Cohen et al. · 2006 · Values writing in one school",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/cohen_et_al._2006_-_reducing_the_racial_achievement_gap.pdf",type:"research",finding:"Two randomized field experiments involved 243 seventh graders at one US school. Approximately fifteen-minute values writing improved targeted course grades for Black students in that setting.",limitation:"No significant effect for White students. A later large replication was null. This does not establish universal academic gains, adult confidence or an immediate mood effect."},{id:"suggestion-S12",title:"Hanselman et al. · 2017 · Large-scale values-affirmation replication",url:"https://files.eric.ed.gov/fulltext/ED578033.pdf",type:"research",finding:"A new-cohort replication across middle schools found no significant targeted GPA benefit. Its precision could reject benefits of at least .10 standard deviations.",limitation:"School context and outcome matter. This does not show all values reflection is useless or disprove health-message findings. The linked text is an accepted manuscript."},{id:"suggestion-S13",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The institutional abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants and confidence interval were unavailable. Task rehearsal does not validate bedtime autosuggestion, a branded ritual or a universal rehearsal dose."},{id:"suggestion-S15",title:"Émile Coué · 1922 English edition · Conscious autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"The historical text prescribes twenty low-voice repetitions on waking and before sleep, counted on knots with closed eyes and without straining.",limitation:"Anecdotes and testimonials are not controlled evidence. Twenty repetitions is historical, not a proven dose. The text’s universal imagination laws and disease-cure claims are unsupported."},{id:"suggestion-S16",title:"Joseph Murphy · The Power of Your Subconscious Mind · publisher synopsis",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The synopsis establishes the book’s provenance and its promotion of belief and imagination.",limitation:"No trial evidence supplied. Exact bedtime phrase, congratulating scene and gratitude passage were unverified. Sleep-memory evidence does not validate drowsy superiority, subconscious attraction or healing."},{id:"suggestion-S17",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Study 1 used one session to identify a desired outcome, obstacle and response, add an if–then plan with usual time and place, then schedule the week.",limitation:"German undergraduate sample; the inspected outcome was scheduled hours, not completed work. No fixed minute dose or special bedtime timing was established."},{id:"suggestion-S18",title:"Louise Hay · What is mirror work?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"The author’s page describes spoken positive statements in a mirror and a 21-day program.",limitation:"Practitioner provenance, not efficacy. No controlled package study was found in the dossier search; this is a search limit. Mirror superiority and a 21-day habit deadline are unestablished."},{id:"suggestion-S19",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher edition",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/9781401938093/",type:"technique",finding:"The publisher identifies the paperback as February 2013; the ebook first appeared in 2012.",limitation:"Promotional synopsis, not controlled evidence. Exact ten-minute routine, gratitude sequence and change cue were unverified. Quantum attraction, genetic commands and healing are not established."},{id:"suggestion-S20",title:"NIMH · Help for mental illnesses",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Official guidance describes routes to qualified mental health and crisis support. Persistent distress, severe impairment and self-harm thoughts warrant appropriate help.",limitation:"ODA is not diagnosis or treatment. Use local services outside the US. Concerning physical symptoms require medical assessment; self-talk must not redefine abuse or real danger as safe."},{id:"murphy-subconscious",title:"Joseph Murphy · The Power of Your Subconscious Mind · publisher synopsis",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The synopsis establishes the book’s provenance and its promotion of belief and imagination.",limitation:"No trial evidence supplied. Exact bedtime phrase, congratulating scene and gratitude passage were unverified. Sleep-memory evidence does not validate drowsy superiority, subconscious attraction or healing."},{id:"expectation-suggestion",title:"Peerdeman et al. · 2016 · Expectation interventions for patients’ pain",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 pooled studies involving 1,256 selected patients found reduced reported pain after expectation interventions: g=.61, 95% CI .42 to .79; bias-adjusted .43, .24 to .62.",limitation:"Clinical interventions differ from a self-written phrase. High heterogeneity; reported pain is not cure of its cause. Anxiety sensitivity estimate after removing an outlier was .03, CI −.21 to .26."},{id:"positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"The abstract reports worse immediate responses for some low-self-esteem participants repeating a strongly positive statement, with limited benefits at higher self-esteem.",limitation:"Original Ns, repetition count and numerical effects were not verified. Two later studies did not reproduce the pattern. No clinical threshold or universal mismatch mechanism is established."},{id:"self-affirmation-health",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Values affirmation paired with health information showed small average differences in message acceptance, intentions and behavior across 144 outcome tests. Behavior: d=.32, 95% CI .19 to .44.",limitation:"144 tests are not necessarily distinct studies. Outcome participant counts overlap. These results do not establish effects of values writing alone, positive chanting or ODA’s short adult exercise."},{id:"distanced-self-talk",title:"Kross et al. · 2014 · Distanced self-talk experiments",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven short experiments involved 585 people. Study 2 used three-minute name or non-first-person reflection before a social interaction and found better observer-rated performance.",limitation:"Mostly student and social-evaluation settings. Preinteraction anxiety did not significantly improve in Study 2; later recovery was clearer. ODA’s shorter advice-and-action adaptation is not treatment or a guaranteed effect."},{id:"sport-self-talk",title:"Hatzigeorgiadis et al. · 2011 · Self-talk and sport performance",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 studies, 62 effects and 2,741 participants found an average sport-task performance benefit: d+=.48, 95% CI .38 to .58. Task and training subgroup estimates varied.",limitation:"Some designs were uncontrolled. Moderator comparisons do not establish optimal doses or universal instructional superiority. Office-work transfer and Gallwey’s whole framework were not tested."},{id:"sleep-memory-reactivation",title:"Paller, Creery & Schechtman · 2021 · Memory and sleep",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"The review discusses reactivation of previously learned material during sleep and limited simple associative sleep learning.",limitation:"Narrative review, no pooled effect. Memory processing does not establish drowsy receptivity to self-help commands, Murphy’s ritual, complex skills installed by recordings or thought-driven outcomes."},{id:"coue-autosuggestion",title:"Émile Coué · 1922 English edition · Conscious autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"The historical text prescribes twenty low-voice repetitions on waking and before sleep, counted on knots with closed eyes and without straining.",limitation:"Anecdotes and testimonials are not controlled evidence. Twenty repetitions is historical, not a proven dose. The text’s universal imagination laws and disease-cure claims are unsupported."},{id:"hay-mirror-work",title:"Louise Hay · What is mirror work?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"The author’s page describes spoken positive statements in a mirror and a 21-day program.",limitation:"Practitioner provenance, not efficacy. No controlled package study was found in the dossier search; this is a search limit. Mirror superiority and a 21-day habit deadline are unestablished."}],a=[{schemaVersion:2,revision:2,id:"suggestion-1",courseId:"suggestion",locale:"en",title:"Your inner critic needs a useful job",goal:"Choose a credible instruction and use it for one real step on your task.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Called yourself useless and left the draft blank? Give that sentence a useful job.",reason:{id:"suggestion-1-reason",label:"What has the criticism cost, and what act matters now?",kind:"text",maxLength:160,optional:!0,suggestions:["A blank application; write a first fact","A delayed correction; check the date","No observed cost yet"]},why:{id:"suggestion-1-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A useful instruction names what to do, such as “Write the first fact.” A flattering verdict names who you supposedly are. Strongly positive statements have mixed evidence: an early study reported worse immediate responses for some participants; two later studies did not reproduce that pattern. Neutral wording does not diagnose you.","Choose a real task serving your direction. Replace the verdict with an instruction, then do one useful piece. Sports research does not prove office-task benefits. Record the act and whether the wording helped, pressured you or did nothing."],example:{title:"Maya’s first fact",text:"At 2:00, Maya sits with her application draft. “I’m hopeless” is familiar; “I’m brilliant” feels false. She tries “Write the first fact” and writes one usable sentence about her experience. She still doubts the application. She records the sentence and unchanged doubt, then schedules another small attempt instead of repeating praise until it feels true."}},move:{invitation:"Name your task and instruction; suggestions show Maya’s application example.",instructions:["Name the actual document, question, or item before saving.","Read the instruction once, then do the matching useful piece."],prompts:[],suggestions:{action:["Write one application sentence using “Write first fact”","Answer the application’s question about work experience"],minimum:["Save one factual work-experience sentence","Save the work-experience answer"],cue:["When lunch ends","After dinner is cleared"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Drop verdict; write one factual application sentence","Ask reviewer which work detail is needed"],observation:["The actual application sentence I saved","Whether wording helped or added pressure"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one application sentence using “Write first fact”",minimum:"Save one factual work-experience sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"The sentence turns into another judgment",fallbackHint:"Drop verdict; write one factual application sentence",observationHint:"The actual application sentence I saved"},stopRule:"Stop wording that increases distress. Choose support for persistent distress; seek care for concerning symptoms.",accessibleAlternative:"Type, dictate or use assistance; neutral task wording is enough."},result:{question:"Did you produce your chosen useful piece?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-1-decision",scenario:"Maya has two minutes and the facts for one application sentence. Praise feels false, and the draft is still blank.",question:"What fits this attempt?",options:[{id:"suggestion-1-praise",text:"Use a warmer positive sentence before deciding whether she can start writing.",feedback:"Warm language is a preference, but she already knows it feels false today. Try a neutral task instruction and make one useful piece without requiring belief in praise."},{id:"suggestion-1-fact",text:"Say “Write the first fact,” then write one usable application sentence.",feedback:"This names an act within her control and tests it immediately. The sentence may help, do nothing or add pressure; her actual output and experience can be recorded."},{id:"suggestion-1-picture",text:"Picture a successful application review, then check whether she feels ready to write.",feedback:"An image may be pleasant preparation, but it does not supply the chosen useful piece. The facts are ready; use an instruction and try the small act."}],bestOptionId:"suggestion-1-fact"}},carry:{takeaway:"Give the sentence a task. Judge it alongside what you actually do.",followUp:{questionId:"suggestion-1-return",question:"What happened with your chosen act, and did the instruction help or add pressure?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Credibility is a choice, not a cutoff",paragraphs:["Wood and colleagues’ accessible abstract reported that a strongly positive statement produced worse immediate responses for some participants with low self-esteem. That abstract does not provide enough detail to prescribe a repetition count or predict an individual response. Two later university analogue studies by Flynn and Bordieri did not reproduce the predicted pattern. The evidence therefore supports uncertainty rather than a settled rule that positive statements harm a particular kind of person. (suggestion-S07; suggestion-S08)","Your preference is still usable information. If “I am brilliant” feels wrong, you can choose “Write the first fact,” edit the wording, skip repetition or stop. A private credibility rating can guide wording, but no score here is a validated clinical threshold. ODA does not infer self-esteem from it or require encouragement. Start with the actual task so the words have a specific job."]},{heading:"Different words, different evidence",paragraphs:["Hatzigeorgiadis and colleagues pooled thirty-two self-talk studies with sixty-two effects in sport and motor tasks. Table 1 reported 2,741 participants. The average performance benefit does not establish the same benefit for application writing, relationships or anxiety. Some study designs were uncontrolled, and subgroup comparisons do not prove a universal ranking of instructional and motivational language. (suggestion-S04)","Today’s neutral instruction and small written piece are an ODA adaptation outside that sport evidence. The combined course has not been tested as a package. Record what you said, what you actually did and any pressure separately. A phrase can be credible without helping action; it can help you start without reducing doubt. Those distinctions give you a reason to keep, edit or stop it rather than treating every repetition as progress toward your chosen life."]}],sourceIds:["suggestion-S07","suggestion-S08","suggestion-S04"]}},{schemaVersion:2,revision:2,id:"suggestion-2",courseId:"suggestion",locale:"en",title:"The ritual ends where the action starts",goal:"Attach your same useful act to a cue that actually occurs.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Repeated the reminder but still left the page blank? Put the action at the cue.",reason:{id:"suggestion-2-reason",label:"If you repeated reminders, what did that give you while the task stayed undone?",kind:"text",maxLength:160,optional:!0,suggestions:["Brief reassurance; the draft stayed blank","Avoided choosing a first sentence","No prior reminder-only attempt"],help:"No prior attempt? Consider what another reminder reading would postpone."},why:{id:"suggestion-2-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Repeating a phrase and repeating an action are different experiments. A habit study tracked eating, drinking and activity at recurring cues. Automaticity developed at different rates; it did not test affirmations. Coué’s twenty repetitions are historical instructions, not a proven dose.","Check your first record. Credible words but no start? Keep the task and choose an event that occurs. “After lunch, write one application sentence” connects cue and act. Read your instruction once if useful, then do the piece. Preparing materials is preparation; writing is the task attempt."],example:{title:"Maya uses lunch",text:"Maya’s first instruction was credible, but she forgot it during a busy morning. She keeps the application task and chooses the end of lunch as her next cue. At the kitchen table she reads “Write the first fact” once and writes a usable sentence. The session stays short. She records the cue and output, without calling it an automatic habit."}},move:{invitation:"Keep your named act; suggestions show Maya’s lunch example.",instructions:["Keep the action and minimum; change a cue only when the record questions it.","For a first plan, name the useful output and actual opening before saving."],prompts:[],suggestions:{action:["After lunch, write one application work-experience sentence","After tea, answer the application’s experience question"],minimum:["Save one factual application sentence","Save the work-experience answer"],cue:["When lunch ends","When I put down my tea"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Write the experience sentence after dinner","Dictate the application sentence at lunch"],observation:["Whether cue and application sentence happened","Reading separately from useful output"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"After lunch, write one application work-experience sentence",minimum:"Save one factual application sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"The lunch cue gets crowded out",fallbackHint:"Write the experience sentence after dinner",observationHint:"Whether cue and application sentence happened"},stopRule:"Skip repetition that adds distress or wakefulness. Preserve care, rest and actual safety needs.",accessibleAlternative:"Use a written, spoken or accessible reminder; no beads or counting required."},result:{question:"Did your cue occur, and did you do the piece?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-2-decision",scenario:"Maya read a credible reminder three mornings but did not write. Her draft and experience facts are ready. Lunch reliably allows one sentence.",question:"What fits this attempt?",options:[{id:"suggestion-2-count",text:"Keep the morning cue and add more repetitions before beginning the draft.",feedback:"More repetition tests phrase reading, not the missing task start. Her records point to cue fit. Use the available lunch opportunity for one actual sentence."},{id:"suggestion-2-cue",text:"Keep credible wording, use lunch as the cue, and write one sentence.",feedback:"This changes the condition that blocked action while preserving the useful task. Record whether the cue occurred and the sentence happened; automaticity is not required."},{id:"suggestion-2-prepare",text:"Use the lunch break to perfect the reminder and arrange tomorrow’s materials.",feedback:"Preparation can serve a missing resource. Her materials and instruction are ready, so another preparation session would leave the same useful sentence undone."}],bestOptionId:"suggestion-2-cue"}},carry:{takeaway:"Cue the useful act, not only the words that precede it.",followUp:{questionId:"suggestion-2-return",question:"Did your chosen cue lead to the act or request, or only reminder reading?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"What Coué’s count can establish",paragraphs:["Coué’s 1922 English text gives historical instructions for twenty low-voice repetitions on waking and before sleep, with closed eyes and knots for counting. The text includes anecdotes, demonstrations and testimonials rather than controlled intervention evidence. The twenty count and twice-daily timing are therefore provenance, not established effective doses. Historical repetition instructions cannot tell you whether today’s wording supports your chosen task. (suggestion-S15)","You do not need to recreate the ritual to test a credible task instruction. Its universal imagination-versus-will laws and disease-cure claims do not follow from the anecdotes. Keep prescribed care and avoid using a reassuring phrase to explain new physical symptoms. The main lesson asks whether your chosen cue supports a useful act. Reading once is optional preparation; the later behavior is what serves the task."]},{heading:"Recurring context is not an instant habit",paragraphs:["Lally and colleagues followed ninety-six volunteers who chose an eating, drinking or activity behavior tied to a recurring context. They tracked repetition and automaticity for eighty-four days. Of eighty-two participants with sufficient data, thirty-nine had acceptable models; their estimated times to near-maximum automaticity varied widely. Some estimates extended beyond observation. The median sixty-six days was not a deadline for every behavior. (suggestion-S09)","This was an observational habit study, not a trial of Coué’s formula, bedtime repetition or an application-writing routine. ODA’s lunch cue and short minimum are design choices. One attempt can show that the cue occurred and the piece was possible; it cannot establish the sentence caused success or that the routine will be automatic by Friday. Keep preparation, cue occurrence and the actual task output distinct when reviewing tomorrow’s record."]}],sourceIds:["suggestion-S15","suggestion-S09"]}},{schemaVersion:2,revision:2,id:"suggestion-3",courseId:"suggestion",locale:"en",title:"Let your value face the feedback",goal:"If feedback blocks your task, connect one chosen value to an actual correction.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Protecting your confidence by avoiding the comments? Let one value guide a real correction.",reason:{id:"suggestion-3-reason",label:"Which useful comment is hardest to use, and what does postponing it cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Vague wording; the reviewer stays confused","Missing date; my application stays incomplete","I need clarification before changing the draft","No usable feedback yet"]},why:{id:"suggestion-3-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Values reflection differs from self-praise. Research pairing it with health information found small average benefits in message acceptance and later behavior. A short values note alone is not proven to improve every task or your mood.","Use this when your record shows feedback avoidance. Keep the task. An optional value, such as learning, can guide one correction. Use “Check this fact,” then correct it or request clarification. Mixed motives and inherited responsibilities count. No perfect reason, agreement with every comment or improved confidence is required."],example:{title:"Maya uses a correction",text:"At her lunch cue, Maya sees a comment that her application sentence is vague. Learning matters to her, but she wants to close the document. She uses “Add one specific example” and revises the sentence with a real task she completed. The whole draft still needs work. She records the correction rather than claiming new confidence from her value."}},move:{invitation:"Keep the named task; suggestions show Maya’s feedback correction.",instructions:["Keep your saved act and cue; identify the comment and its actual correction.","A value may help; correcting or requesting clarification supplies the act."],prompts:[],suggestions:{action:["Add one work example to the application sentence","Ask reviewer which application sentence needs detail"],minimum:["Save the application sentence with one example","Send the application-detail clarification question"],cue:["When lunch ends","When the reviewer’s comment arrives"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Add one known work fact without defending","Ask reviewer which detail needs clarification"],observation:["The corrected sentence or actual clarification question","Whether I used the relevant feedback"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Add one work example to the application sentence",minimum:"Save the application sentence with one example",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I want to defend the whole draft instead",fallbackHint:"Add one known work fact without defending",observationHint:"The corrected sentence or actual clarification question"},stopRule:"Keep boundaries around hostile or unsafe feedback; choose protection or support when needed.",accessibleAlternative:"Choose a private value, neutral instruction or assistance; values writing is optional."},result:{question:"Did you make the correction or ask your question?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-3-decision",scenario:"Maya’s safe reviewer identifies one vague sentence. She has a concrete example and values learning, but feels defensive.",question:"What fits this attempt?",options:[{id:"suggestion-3-strengths",text:"List her strengths first, then revisit the sentence when the criticism feels easier.",feedback:"Strengths reflection may be a preference, but the usable example is available now. Her value can guide one correction without making comfort an entry requirement."},{id:"suggestion-3-correct",text:"Use “Add one example” and revise the sentence with the fact she has.",feedback:"This turns learning into a concrete choice on the same task. The correction is observable evidence; it does not require improved mood or agreement with every comment."},{id:"suggestion-3-reassure",text:"Ask the reviewer to confirm her overall ability before making the specific correction.",feedback:"Reassurance could feel helpful, but overall ability is not the missing information. Use the specific comment and available fact; request clarification only when details are unclear."}],bestOptionId:"suggestion-3-correct"}},carry:{takeaway:"A value becomes useful when it guides a choice you actually make.",followUp:{questionId:"suggestion-3-return",question:"Did you make the correction or clarification request, and what is still unclear?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Values reflection has context-specific evidence",paragraphs:["Epton and colleagues combined self-affirmation tests paired with health information. They found small average effects on message acceptance, intentions and behavior. The 144 tests span outcomes and are not necessarily 144 distinct studies; their participant totals must not be summed as unique people. Values reflection in that setting is different from chanting praise or claiming excellence before looking at feedback. (suggestion-S02)","A newer review by Zhang and colleagues reported small well-being benefits across sixty-seven articles and 129 independent tests in nonclinical populations. The available institutional abstract gives a broad summary, without the full methods needed to assess the precise effect metric, participant total, confidence intervals or follow-up durations. This broadens the context beyond health messages, but does not establish a benefit from today’s brief value-and-correction exercise or a particular affirmation script. (suggestion-S05)"]},{heading:"Use a value without making a universal promise",paragraphs:["A large middle-school replication by Hanselman and colleagues found no significant targeted grade-point benefit from values affirmation in its new cohort. The reported precision could reject benefits of at least .10 standard deviations. This does not mean all values reflection is useless or disprove health-message findings; it means context, population and outcome matter. A school result cannot promise adult confidence or a general performance boost. (suggestion-S12)","ODA’s practical question is narrower: does remembering a value help you use one relevant piece of feedback on your continuing task? A brief optional note and this specific correction are adaptations. You can care about learning, responsibility to family or getting a job for several reasons at once. No motive-purity test is needed. Keep useful feedback distinct from insults or unsafe demands, and record the actual correction or help request rather than a more positive self-description."]}],sourceIds:["suggestion-S02","suggestion-S05","suggestion-S12"]}},{schemaVersion:2,revision:2,id:"suggestion-4",courseId:"suggestion",locale:"en",title:"Nervous? Give yourself clear advice.",goal:"If self-focused worry blocks participation, try name-based reflection and use your prepared line.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Know your point but keep rehearsing your nerves? Address yourself once, then use the point.",reason:{id:"suggestion-4-reason",label:"What does more self-analysis give you, and what opportunity could it cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Polished wording; miss the reviewer’s invitation","Brief reassurance; postpone the ready question","An unclear question still needs preparation","No prior missed opening"]},why:{id:"suggestion-4-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["In short social-stress experiments, people reflected using their name or “you” rather than “I.” One study found better observer-rated interaction performance, without a significant reduction in anxiety beforehand. Perspective is not a command to remove nerves.","If self-focused worry blocked your task, keep the facts matched: “I’m prepared and nervous” becomes “Maya is prepared and nervous.” Add one useful instruction, then use your line in the safe interaction. Keep an earlier instruction if it works. Name-based reflection is optional preparation; participation is the actual attempt."],example:{title:"Maya asks the reviewer",text:"Maya has a prepared question about her application, but her lunch record shows she kept analyzing how she would sound. Before a safe call, she says, “Maya is prepared and nervous. Ask about the example.” She asks her question. The reviewer needs time to answer. Maya records the participation and pending reply, not a pronoun trick that erased anxiety."}},move:{invitation:"Keep your actual act; suggestions show a reviewer question.",instructions:["Keep the named action and cue; reflection is optional preparation.","For a first interaction, name the actual question and a safe opening.","Ask or share the prepared line; you can use ordinary first-person wording."],prompts:[],suggestions:{action:["Ask reviewer which work example the application needs","Share the application sentence with the reviewer"],minimum:["Ask which work example is missing","Send the application sentence for review"],cue:["When the reviewer invites questions","When lunch ends"],place:["In the scheduled review call","In the reviewer’s message thread"],minutes:[2,1,3],fallback:["Ask “Which work example is missing?” now","Send reviewer the work-example question"],observation:["Whether I actually asked the work-example question","The response, including a pending reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask reviewer which work example the application needs",minimum:"Ask which work example is missing",minutes:2,cueHint:"When the reviewer invites questions",placeHint:"In the scheduled review call",obstacleHint:"I continue analyzing instead of asking the ready question",fallbackHint:"Ask “Which work example is missing?” now",observationHint:"Whether I actually asked the work-example question"},stopRule:"Pause unsafe interactions. Seek qualified support for persistent distress or severe impairment.",accessibleAlternative:"Use a safe written, signed or assisted line; name-based reflection is optional."},result:{question:"Did you use your prepared line in the interaction?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-4-decision",scenario:"Maya has a clear application question. Her scheduled reviewer invites it now before the call ends. She is nervous and has already reflected briefly.",question:"What fits this attempt?",options:[{id:"suggestion-4-name",text:"Rehearse privately once more to polish the wording, then ask at the reviewer’s next invitation.",feedback:"One rehearsal may polish the wording. Her question is already clear, and the call is ending. Use this safe opening; name-based reflection is optional, and a factual first-person instruction also works."},{id:"suggestion-4-analyze",text:"Explain the nervousness privately in more detail before deciding whether to participate.",feedback:"Detailed reflection can help another question, but it prolongs preparation here. Her current bottleneck is using the ready line while the safe opening is available."},{id:"suggestion-4-use",text:"Use “Maya is prepared and nervous,” then ask her actual question.",feedback:"This preserves the facts and ends preparation in participation. The laboratory evidence does not promise less anxiety beforehand; record the actual line and response."}],bestOptionId:"suggestion-4-use"}},carry:{takeaway:"Perspective should end in advice and an act, not another round of self-analysis.",followUp:{questionId:"suggestion-4-return",question:"Did the perspective prompt end in your real line or more preparation?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Change perspective without changing the facts",paragraphs:["Kross and colleagues conducted seven experiments with 585 people, mostly in student and social-evaluation settings. In Study 2, participants reflected alone for three minutes before meeting an unfamiliar person. The experimental instruction used their own name and non-first-person pronouns; the comparison used “I” and “me.” The name-based group had better observer-rated interaction performance. Preinteraction anxiety did not significantly improve; recovery afterward was clearer. (suggestion-S03)","The honest illustration keeps content matched. Compare “I’m prepared and nervous; start with the first fact” with “Maya is prepared and nervous; start with the first fact.” Comparing harsh first-person criticism with kind name-based advice would also change kindness, so it cannot isolate perspective. ODA’s brief advice-and-line version is an adaptation, not the three-minute protocol or a treatment for social anxiety."]},{heading:"Clear advice still needs an opening",paragraphs:["The short experiments do not establish a lasting benefit, a required pronoun or a universal advantage in every setting. Ordinary first-person thinking is not itself harmful. You may prefer “I can ask the question,” neutral instructions or no reflection. The continuing course experiment still concerns the useful task you chose, not speaking to yourself in a particular grammatical form. (suggestion-S03)","Save the real interaction as the act when that is your next task step. If you only prepare the line, record preparation rather than inventing participation. A missing opening can be reported as no occasion. Persistent distress, severe impairment or self-harm thoughts warrant qualified help; name-based reflection does not replace it. Protect yourself in unsafe situations and use appropriate local support. No pronoun change makes abuse safe or removes a need for care. (suggestion-S20)"]}],sourceIds:["suggestion-S03","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-5",courseId:"suggestion",locale:"en",title:"After the error, name the next move",goal:"If your task has a recurring error, test one specific cue on an actual item.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Another mistake, another verdict about yourself? Give the next attempt one concrete instruction.",reason:{id:"suggestion-5-reason",label:"After your last error, which judgment delayed the actual correction?",kind:"text",maxLength:160,optional:!0,suggestions:["“I am careless”; left the date unchanged","“This draft is hopeless”; stopped checking","No judgment delayed my correction","No prior error; I may judge myself"],help:"No prior error? Name a judgment that could delay fixing the next one."},why:{id:"suggestion-5-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sports self-talk studies found an average performance benefit across varied tasks and training methods. Instruction sometimes fit precision tasks better, but comparisons do not establish universal superiority over encouragement or the same effect in office work.","Check your task record. For a recurring detail, name its cue: “Check the date.” If needed, try an easy practice item, then one real item. Record them separately. When you do not know how to fix the error, request instruction. Stronger motivation cannot supply missing knowledge or complete the correction."],example:{title:"Maya checks the date",text:"Maya’s application draft has two inconsistent dates. At the lunch cue, she says “Check the date.” She tries one copied example as preparation, then checks and corrects one real date in her draft. A second discrepancy remains. She records the actual correction and asks for guidance on the unclear entry, without claiming the cue solved the whole draft."}},move:{invitation:"Keep your actual item and cue; suggestions show an application-date correction.",instructions:["Keep the saved item and opening; name its actual checking instruction.","For the example, use “Check the date” and correct one application entry.","If the procedure is unknown, choose Adapt to request specific instruction."],prompts:[],suggestions:{action:["Use “Check the date”; correct one application entry","Compare one application date with the original record"],minimum:["Save one corrected date in the application","Record whether the application date matches"],cue:["When lunch ends","When I reach the application’s dates section"],place:["At my kitchen table","In the application draft"],minutes:[3,2,1],fallback:["Ask reviewer how to verify the date","Check the original dated work record"],observation:["The actual date correction or instruction request","Practice item separately from real work"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “Check the date”; correct one application entry",minimum:"Save one corrected date in the application",minutes:3,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I do not know how to verify the correct date",fallbackHint:"Ask reviewer how to verify the date",observationHint:"The actual date correction or instruction request"},stopRule:"Need instruction? Choose Adapt this, then Support. For consequential tasks, get appropriate professional guidance.",accessibleAlternative:"Use a written cue, accessible example, dictation or assistance."},result:{question:"Did you correct a real item or request instruction?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-5-decision",scenario:"Maya knows how to check a date but repeatedly skips that step. One real application entry needs correction.",question:"What fits this attempt?",options:[{id:"suggestion-5-drive",text:"Use “Keep going” while completing the remaining batch to preserve momentum.",feedback:"Momentum matters, but this record identifies a skipped check. Name that detail and test it on one real entry rather than carrying the same error through the batch."},{id:"suggestion-5-detail",text:"Use “Check the date” on one real entry, then correct it.",feedback:"The cue matches the observed bottleneck and produces an actual correction. This personal trial gives feedback about fit, not proof of the cue’s causal effect."},{id:"suggestion-5-all",text:"Write a short checklist for dates, labels and formatting before returning to the application entry.",feedback:"A short checklist can prevent several omissions. This record names one skipped date check, and Maya knows the procedure. Correct that real entry first; add other checks when they address observed needs."}],bestOptionId:"suggestion-5-detail"}},carry:{takeaway:"Correct the next workable detail; ask for instruction when the skill is missing.",followUp:{questionId:"suggestion-5-return",question:"What happened with the correction or instruction request, and what detail still needs checking?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A sport average is not an office promise",paragraphs:["Hatzigeorgiadis and colleagues’ meta-analysis pooled thirty-two studies and sixty-two effects. The primary table reported 2,741 participants. The overall corrected standardized performance difference was .48, with a confidence interval from .38 to .58. Studies involved sport and motor tasks, including students and athletes; some designs lacked controlled comparisons. A pooled sport result cannot specify what will happen in your application draft or choose a checking rule for you. (suggestion-S04)","Subgroup estimates varied for fine and gross motor tasks, instructional and motivational wording, and prior training. Those are not randomized dose comparisons or a universal technique ranking. They do not predict a .48 benefit for a spreadsheet, application or conversation. Today’s one-cue, one-real-item trial is an ODA transfer experiment. Keep a favorable result modest: it shows what happened on that item, not why it happened or what every later attempt will do."]},{heading:"Instruction has to name a usable detail",paragraphs:["The cue should answer the actual problem in your record. “Check the date” names a step; “be excellent” does not explain how to correct one. An easy example can prepare the cue, but it is not completion of the real item. If a procedure is unfamiliar, a concrete request for instruction is a useful act in its own right. The sport review does not validate Gallwey’s whole framework, two literal neural selves or an unverified historical script. (suggestion-S04)","You may change the cue after observing a mismatch, retain it after a workable attempt or stop using self-talk if it adds pressure. Do not introduce several new instructions simply to create a more impressive plan. ODA’s record is a way to identify the bottleneck, not a grade on character. Persistent or severe distress warrants qualified support rather than stronger repetition. (suggestion-S20)"]}],sourceIds:["suggestion-S04","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-6",courseId:"suggestion",locale:"en",title:"Let bedtime be bedtime",goal:"If tomorrow’s obstacle is unclear, plan earlier and save the actual task attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bedtime pep talk keeping you awake? Give tomorrow a cue while you are awake.",reason:{id:"suggestion-6-reason",label:"What needs a plan, and what needs rest?",kind:"text",maxLength:160,optional:!0,suggestions:["Lunch is crowded; choose another daytime cue","The plan is ready; stop bedtime checking","I have no observed planning problem yet"]},why:{id:"suggestion-6-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sleep helps process memories; this does not establish a special window for subconscious commands. Outcome, obstacle and response planning has evidence across goals, but research does not validate bedtime fantasy followed by next-morning planning.","Address an unhandled obstacle earlier while awake. Name the desired result, obstacle and feasible response together. Keep the same useful task piece as the act. Planning is preparation; save and record the later attempt separately. Stop bedtime thinking if it increases wakefulness. No scene, gratitude feeling or repetition is required to make the plan valid."],example:{title:"Maya plans before dinner",text:"At 6:30, Maya wants tomorrow’s application sentence, but expects breakfast to be crowded. She chooses the lunch cue and a response: dictate a sentence if her table is occupied. The note is preparation. Next day the table is busy, so she dictates one usable sentence. She records the actual output. At bedtime she leaves the plan alone."}},move:{invitation:"Keep your named task; suggestions show Maya’s daytime writing example.",instructions:["Keep the saved act, minimum, and cue unless one obstacle needs a change.","Plan outcome, obstacle, and response together while awake; record the later act separately."],prompts:[],suggestions:{action:["Write one application work-experience sentence after lunch","Dictate the application work-experience sentence after lunch"],minimum:["Save one factual application sentence","Save one dictated work-experience sentence"],cue:["When lunch ends","After my morning drink"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Dictate the application sentence at lunch","Write the experience sentence after dinner"],observation:["Whether the table was available and fallback used","The actual application sentence after preparation"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one application work-experience sentence after lunch",minimum:"Save one factual application sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"My kitchen table is occupied",fallbackHint:"Dictate the application sentence at lunch",observationHint:"Whether the table was available and fallback used"},stopRule:"Stop bedtime planning if it increases wakefulness. Preserve rest and seek appropriate help for persistent concerns.",accessibleAlternative:"Plan by typing, speaking or assistance while awake; imagery is optional."},result:{question:"Did you do the actual piece at your cue?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-6-decision",scenario:"Maya has a written lunch plan. In bed, imagining tomorrow turns into repeated anxious checking and she feels more awake.",question:"What fits this attempt?",options:[{id:"suggestion-6-finish",text:"Complete the obstacle analysis in bed so tomorrow’s plan feels fully settled.",feedback:"Completeness is tempting, but a workable plan is already written and this checking increases wakefulness. Stop now; review details earlier while awake if they need changing."},{id:"suggestion-6-stop",text:"Stop the scene, leave the written cue in place, and return to rest.",feedback:"This protects rest without discarding tomorrow’s feasible act. Sleep-memory findings do not establish a required bedtime ritual. The later task attempt gets its own record."},{id:"suggestion-6-replace",text:"Replace the scene with a repeated positive phrase until the checking quiets.",feedback:"A different ritual may continue the same wakeful effort. No repetition is required to make the plan valid. Leave the cue in place and stop planning now."}],bestOptionId:"suggestion-6-stop"}},carry:{takeaway:"Make the plan while awake. Let rest and the later act have separate records.",followUp:{questionId:"suggestion-6-return",question:"Did the obstacle response support your actual act without extending bedtime effort?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Sleep science does not certify a ritual",paragraphs:["Paller, Creery and Schechtman’s review discusses reactivation of previously learned material during sleep and limited simple associative learning. It is a narrative synthesis with no pooled effect for self-help suggestion. Memory processing does not establish an uncritically receptive subconscious before sleep, a drowsy advantage for affirmations or complex skills installed by a phrase. Those are different claims. (suggestion-S10)","Murphy’s publisher synopsis establishes book provenance and promotes belief and imagination. The publisher’s synopsis does not establish that Murphy’s bedtime ritual works. It supplies no controlled evidence for the named package and cannot validate a specific repetition script. If planning adds wakefulness, move any needed planning to an earlier daytime opportunity and leave bedtime for rest. A voluntary daytime image is still an ODA choice, not evidence of attraction, healing or a special bedtime mechanism. (suggestion-S16)"]},{heading:"Keep outcome, obstacle and response together",paragraphs:["Wang and colleagues’ meta-analysis of mental contrasting with if–then plans included twenty-one articles, twenty-four independent effects and 15,907 participants. It found an average goal-attainment benefit; publication-bias adjustment reduced the estimate. Goals, methods and comparisons varied. The result does not isolate a positive sentence as the active ingredient or validate the assembled ODA suggestion card. (suggestion-S06)","Use the contrast to answer a concrete planning problem: what outcome matters, what obstacle is likely, and what response is feasible? Work through those parts together, then save the actual task piece with its cue. A note about tomorrow is preparation today, not tomorrow’s completed work. If the obstacle requires resources, safety or assistance, choose that practical response rather than blaming belief. Moving planning earlier protects the opportunity for rest; the research did not test a bedtime-fantasy and next-morning-plan split."]}],sourceIds:["suggestion-S10","suggestion-S16","suggestion-S06"]}},{schemaVersion:2,revision:2,id:"suggestion-7",courseId:"suggestion",locale:"en",title:"Count the moves, not the card reads",goal:"Consolidate your same task records and choose the next workable instruction-and-action attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reminder read, task untouched? Review actual pieces, or plan a first trial.",reason:{id:"suggestion-7-reason",label:"What will you keep, change or stop from your records?",kind:"text",maxLength:160,optional:!0,suggestions:["Lunch worked; keep that opening","Morning was crowded; change that cue","Repetition added pressure; stop repeating","No attempt recorded; choose a first act"]},why:{id:"suggestion-7-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A credible sentence, cue and obstacle response can fit together, but this assembled card is not validated as a package. Planning research does not establish that card reading causes action.","Review your task, or choose a first trial. Separate reminder reads, preparation, actual acts and returns. Keep acceptable wording and a workable cue; change one observed bottleneck. Save the same act and minimum for the next opportunity. Later dates stay plans until reported. If wording adds pressure, simplify or stop it. No mirror, new ritual or stronger belief is required."],example:{title:"Maya’s next week",text:"On Sunday, Maya sees five reminder reads and three useful application pieces. Two missed starts used a crowded morning cue; lunch worked twice. She keeps “Write the first fact,” drops extra imagery and schedules Monday’s lunch attempt. On Monday she writes a sentence that still needs editing. She records the piece and keeps next week’s other dates as plans."}},move:{invitation:"Keep your chosen act and minimum; suggestions are application examples.",instructions:["Keep the actual act, minimum, cue, and place; change only the observed bottleneck.","With no record, name a first act and its matching minimum before saving.","Use Adapt for a support request; later dates remain plans."],prompts:[],suggestions:{action:["Use “Check the date”; correct one application entry","Compare one application date with the original record"],minimum:["Save one corrected date in the application","Record whether the application date matches"],cue:["When lunch ends","When I reach the application’s dates section"],place:["At my kitchen table","In the reviewer’s message thread"],minutes:[2,1,3],fallback:["Stop reading; verify one application date","Ask reviewer which date source to use"],observation:["Actual corrections separately from card reads","Whether the lunch opening and instruction fit"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “Check the date”; correct one application entry",minimum:"Save one corrected date in the application",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I keep reading instead of checking the application date",fallbackHint:"Stop reading; verify one application date",observationHint:"Actual corrections separately from card reads"},stopRule:"For task help, choose Adapt this, then Support. Stop distressing wording; seek qualified care for persistent distress or impairment. Keep prescribed care.",accessibleAlternative:"Use a private accessible note, neutral wording or assistance; no mirror required."},result:{question:"Did you do the next piece or chosen support act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-7-decision",scenario:"Maya read her card daily but wrote once at lunch. Mornings were crowded; the instruction still felt credible.",question:"What fits this attempt?",options:[{id:"suggestion-7-repeat",text:"Preserve the morning plan because daily card reading shows the routine is taking hold.",feedback:"Daily reading is a real process record, but it is not the chosen writing outcome. Her cue rarely led to work. Test the lunch opportunity instead."},{id:"suggestion-7-increase",text:"Add an evening reading so the credible sentence becomes easier to recall.",feedback:"Recall may matter, but the available evidence points to crowded mornings. More reading changes repetition while leaving the task cue unchanged; test the observed bottleneck first."},{id:"suggestion-7-revise",text:"Keep the credible sentence, use lunch, and schedule one actual writing piece.",feedback:"This preserves what fit and changes the cue linked to missed starts. The next piece remains a plan until reported; use tomorrow’s return to judge the new attempt."}],bestOptionId:"suggestion-7-revise"}},carry:{takeaway:"Keep useful words only with a workable act, an honest record and a next choice.",followUp:{questionId:"suggestion-7-return",question:"What happened with your chosen act or support request, and what needs to change?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"The assembled card is a design choice",paragraphs:["The course joins credible wording, one cue, an actual task piece, an obstacle response and a return record. This combination is an ODA design, not a controlled intervention package. Wang and colleagues’ review supports mental contrasting with if–then plans across varied goals, but does not establish that every card ingredient helps or that reading the card is the cause of any completed task. (suggestion-S06)","Use the card as a compact reminder of your saved plan rather than a new requirement. Review preparation separately from the useful piece. A card read can be reported honestly without counting it as writing, asking or correcting. Keep one observed bottleneck in view so the next trial answers something specific. A favorable personal record is feedback about fit, not causal proof or a guarantee that the same plan will work in every week."]},{heading:"No new ritual is needed at the finish",paragraphs:["Lally’s observational habit study concerned eating, drinking and activity behaviors repeated at recurring cues. It did not test positive phrases or guarantee a deadline for automaticity. ODA’s next-week opportunities and review interval are choices for organizing your experiment, not a tested dose or a requirement for an unbroken streak. Actual task attempts remain separate from learning completion. (suggestion-S09)","Hay’s author page describes mirror statements and a twenty-one-day program. No controlled study of that named package was located in the evidence review; this does not prove it has never been studied. Mirror delivery has no established superiority here, and twenty-one days is not a habit deadline. A private note, accessible reminder or no card can suit your preference. Finish by carrying your same useful task forward, adjusting from records and protecting safety, rest and prescribed care. (suggestion-S18)"]}],sourceIds:["suggestion-S06","suggestion-S09","suggestion-S18"]}}],i=[{id:"suggestion-1",practice:["Name one ordinary situation you would like to approach differently this week.","Compare the familiar critic sentence with a credible neutral instruction; imagery and encouragement are optional.","Try the instruction with one useful task piece; note the actual behavior and any pressure separately."],reflection:"Which sentence do you say to yourself most often, and how does it affect you?",question:"How is suggestion defined in this course?",options:["A secret command sent to the subconscious that changes everything by itself.","Repeating a chosen sentence, an image and a small action together.","A thinking technique that can replace medication or treatment."],correct:1,feedback:"The course uses an untested instruction-and-action experiment; imagery is optional. Clinical expectation studies do not validate the combined routine. Suggestion does not replace treatment or guarantee external results.",photo:{id:"1461468611824-46457c0e11fd",alt:"Woman sitting and looking out at the sea"}},{id:"suggestion-2",practice:["If you choose to explore Coué’s historical ritual, check that the wording is acceptable; counting materials are optional.","His 1922 English text described twenty quiet repetitions; this is history, not a proven dose or required bedtime practice.","If you voluntarily try wording, stop for distress or wakefulness and keep phrase reading separate from actual task action."],reflection:"How did it feel to say the formula without forcing it: soothing, strange, boring?",question:"Which of these fits the attitude Coué recommended for his formula?",options:["Saying the sentence as forcefully as possible, through gritted teeth.","Saying the sentence in a relaxed, low voice and leaving the counting to the string or beads.","Checking after every repetition whether something has changed."],correct:1,feedback:"Coué recommended relaxed repetition in his historical account. Anecdotes do not establish a universal imagination law, an effective twenty-repetition dose or disease cures. The opened English edition is from 1922.",photo:{id:"1762328490563-9b9c300fba3e",alt:"Person holding a string of beads"}},{id:"suggestion-3",practice:["Choose a positive sentence or a neutral task instruction you find acceptable.","Optionally rate credibility to guide wording, without a clinical cutoff; edit or stop if it adds distress.","Optionally reflect on an important value, then choose one concrete task action that serves it."],reflection:"Which sentence makes you think, “yes, that could be true”?",question:"With mixed findings about positive self-statements, which wording can you choose to test?",options:["Repeating the boldest sentence more often, even if you do not believe it.","Choosing a sentence you can believe that describes a process.","Never saying any positive sentence to yourself."],correct:1,feedback:"The early backfire report was not reproduced in two later studies. Neutral or process wording is a voluntary preference, not proven safer treatment. Credibility scores do not diagnose self-esteem.",photo:{id:"1616628188467-8fb29f49bbe8",alt:"Hand writing a note on white paper"}},{id:"suggestion-4",practice:["Pick a moment this week that will be hard for you, and note its time.","Before that moment, take two minutes to describe the situation to yourself, calling yourself by name.","Then say to yourself the supportive sentence you would say to a friend in the same situation."],reflection:"How did your tone change when you called yourself by name?",question:"In Kross’s 2014 experiments, which kind of self-talk was more helpful under social stress?",options:["Calling yourself by name or “you”.","Thinking about the situation at length, using only “I”.","Motivating yourself with harsh criticism."],correct:0,feedback:"Short social-stress experiments found better observer-rated performance with name or non-first-person reflection. Study 2 did not significantly reduce anxiety before interaction; recovery afterward was clearer. This is not treatment.",photo:{id:"1641907173006-6b8930ae1191",alt:"Woman looking up at the sky, lost in thought"}},{id:"suggestion-5",practice:["Choose a task this week that you find hard to learn or to do well.","Write one instructional and one motivational cue word for that task.","While doing the task, repeat the cue in a short, calm voice, and note the result without judging it."],reflection:"Which cue actually drew your attention into the task?",question:"According to the meta-analysis, when did instructional self-talk work especially well?",options:["In tasks that need fine skill and attention.","Only in very well-learned, automatic tasks.","On the first attempt only, with no practice at all."],correct:0,feedback:"In sport studies, instructional cues often fit fine or new tasks; some designs were uncontrolled. Task and training subgroup comparisons do not prove a universal ranking, optimal dose or equivalent office-work benefit.",photo:{id:"1523497804259-88c4c134ca90",alt:"Athlete getting ready to run on a track"}},{id:"suggestion-6",practice:["While awake earlier in the day, name your desired outcome and one real obstacle together.","Choose a feasible obstacle response and an actual useful task piece; optional imagery remains preparation.","Save the actual task cue and record its later attempt separately. Stop bedtime planning if it increases wakefulness."],reflection:"What did the scene you built before sleep remind you of in the morning?",question:"Which preparation keeps the suggestion claims within the evidence?",options:["Imagining the result and also adding the real obstacle and an if–then plan.","Waiting for the subconscious to attract money and health by itself during sleep.","Only imagining the good outcome and making no plan at all."],correct:0,feedback:"Outcome, obstacle and response planning has evidence across varied goals. That does not validate a special drowsy ritual or a bedtime-fantasy and next-morning-plan split. Preserve sleep; later action is separate.",photo:{id:"1757796859729-270d1e3ad4d5",alt:"Open book on a nightstand under a lit lamp"}},{id:"suggestion-7",practice:["If a card is useful, write your credible instruction and optional first-step image; use an accessible private format.","Add your actual task cue and feasible obstacle response; reading the card is not doing the task.","Choose a review date, then compare actual attempts with preparation after they occur; a week is not a validated dose."],reflection:"After seven days, what on your card would you keep exactly as it is, and what would you change?",question:"When you review your suggestion card after seven days, which approach is most useful?",options:["Blaming yourself if nothing has changed.","Looking at what worked and adjusting the sentence, the image or the plan.","Starting to say a bolder sentence more loudly."],correct:1,feedback:"Review actual task attempts separately from card reads. The combined card is untested; keep useful wording and change an observed bottleneck without requiring mirrors, stronger belief or a new ritual.",photo:{id:"1484480974693-6ca0a78fb36b",alt:"Hand writing a checklist in a notebook"}}],o={id:"suggestion",title:"Inner critic stalling you? Give it a useful job",subtitle:"Seven short lessons. Use credible words for one useful act, then revise from what actually happened.",description:"Choose one meaningful task and test a believable instruction alongside real action. Improve its cue, use feedback, address an observed obstacle and carry the same experiment into next week.",scope:"A course in self-suggestion and self-talk for adults. It is not hypnotherapy, diagnosis or treatment. Suggestion does not replace medication or any treatment you are receiving; do not stop a medication or treatment without talking to your doctor. The claims in some books that suggestion cures illness or attracts money are not supported by research. If the negative sentences inside you are very intense, or you have felt low for a long time, reach out to a mental health professional. If you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"A credible instruction tied to a useful task, an honest action record, and a next attempt shaped by evidence from your day.",photo:{id:"1779922811108-245a9403ef44",alt:"Silhouette of a person standing on a hilltop at dawn"},lessons:a.map((e,t)=>({...i[t],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"suggestion-S20",...e.id==="suggestion-3"?["suggestion-S07","suggestion-S08"]:[]])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"One continuing experiment",steps:[{label:"Cue",text:"Choose a workable opening."},{label:"Act",text:"Try the useful minimum."},{label:"Return",text:"Record and choose the next attempt."}]}}))};export{o as COURSE,n as SOURCES,a as SUGGESTION_LESSONS_V2};
